    ) internal view {
        // TODO(EXSC-626): migrate to LibBytes.toBytes32 — see LibBytes v1.1.0
        bytes32 receiverBytes32 = _bridgeData.receiver == NON_EVM_ADDRESS
            ? _nearData.nonEVMReceiver
            : bytes32(uint256(uint160(_bridgeData.receiver)));

        bytes32 structHash = keccak256(
            abi.encode(
                NEARINTENTS_PAYLOAD_TYPEHASH,
                _bridgeData.transactionId,
                _bridgeData.minAmount,
                receiverBytes32,
                _nearData.depositAddress,
                _bridgeData.destinationChainId,
                _bridgeData.sendingAssetId,
                _nearData.deadline,
                _nearData.quoteId,
                _nearData.minAmountOut,
                _nearData.destinationAsset,
                _nearData.refundRecipient
            )
        );

        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", _domainSeparator(), structHash)
        );

